def american_probability(value):
    if isinstance(value, bool):
        raise ValueError("bool is not a valid odds value")
    if type(value) is int:
        if abs(value) < 100:
            raise ValueError("odds must have absolute value >= 100")
        if value > 0:
            return 100 / (value + 100)
        else:
            return -value / (-value + 100)
    elif type(value) is float:
        if not math.isfinite(value):
            raise ValueError("odds must be finite")
        if abs(value) < 100:
            raise ValueError("odds must have absolute value >= 100")
        if value > 0:
            return 100.0 / (value + 100.0)
        else:
            return -value / (-value + 100.0)
    elif type(value) is str:
        s = value.strip()
        if not s:
            raise ValueError("empty string is not a valid odds value")
        try:
            f = float(s)
        except ValueError:
            raise ValueError("invalid numeric string")
        if not math.isfinite(f):
            raise ValueError("odds must be finite")
        if abs(f) < 100:
            raise ValueError("odds must have absolute value >= 100")
        if f > 0:
            return 100.0 / (f + 100.0)
        else:
            return -f / (-f + 100.0)
    else:
        raise ValueError("unsupported type for odds")

